//! No `tracing` macro anywhere in the workspace may pass `target` or `parent`
//! with `=` instead of `:` — the `=` form silently records an ordinary field
//! and leaves the event on its module-path target (SMA-543).

use std::path::{Path, PathBuf};

use paigasus_helikon_workspace_lints::try_scan;

/// Repo root, derived from this crate's manifest directory rather than the
/// process CWD so it survives the member being moved.
fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .canonicalize()
        .expect("repo root must resolve from CARGO_MANIFEST_DIR")
}

/// Collect `.rs` files under `dir`, skipping build output.
///
/// Uses [`std::fs::symlink_metadata`] rather than [`Path::is_dir`] on each
/// entry: `is_dir` follows symlinks, so a symlink pointing at an ancestor
/// directory would recurse this walk unboundedly, and a broken `.rs`
/// symlink would panic the later `read_to_string` call in the test proper.
/// Symlinks of either kind are skipped outright.
fn collect_rs(dir: &Path, out: &mut Vec<PathBuf>) {
    let entries = std::fs::read_dir(dir).unwrap_or_else(|e| panic!("read_dir {dir:?}: {e}"));
    for entry in entries {
        let path = entry.expect("dir entry").path();
        let meta = std::fs::symlink_metadata(&path)
            .unwrap_or_else(|e| panic!("symlink_metadata {path:?}: {e}"));
        if meta.is_symlink() {
            continue;
        }
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_default();
        if meta.is_dir() {
            if name == "target" || name == ".git" {
                continue;
            }
            collect_rs(&path, out);
        } else if name.ends_with(".rs") {
            out.push(path);
        }
    }
}

